import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import ts from 'typescript';
const evidence = JSON.parse(readFileSync('benchmarks/results/validation-v0.15-windows.json'));
const surface = (path) => {
  const source = ts.createSourceFile(path, readFileSync(path, 'utf8'), ts.ScriptTarget.Latest, true);
  return source.statements.filter(ts.isExportDeclaration).flatMap(statement => {
    assert.ok(statement.exportClause && ts.isNamedExports(statement.exportClause));
    return statement.exportClause.elements.map(element => ({name: element.name.text, kind: statement.isTypeOnly || element.isTypeOnly ? 'type' : 'value', module: statement.moduleSpecifier.text}));
  }).sort((a,b) => a.name.localeCompare(b.name));
};
assert.equal(evidence.publicSurface.source.length, 38);
assert.deepEqual(surface('packages/runtime/src/index.ts'), evidence.publicSurface.source);
assert.deepEqual(surface('packages/runtime/dist/index.d.ts'), evidence.publicSurface.source);
assert.deepEqual(Object.keys(await import('@pjs/runtime')).sort(), evidence.publicSurface.runtimeValues);
assert.deepEqual(evidence.separateConsumers.installedRuntimeExports, evidence.publicSurface.runtimeValues);
assert.equal(evidence.publicSurface.runtimeValues.length, 16);
console.log('38 named exports: 16 runtime values and 22 type-only exports; source, declarations, inventory and installed consumer match.');
